sources={"/var/lib/rea-reversa":"state","/var/www/rea-reversa-acme":"acme","/var/lib/rea-mcp-oauth":"oauth_alias","/var/lib/private/rea-mcp-oauth":"oauth_state"}
out={"project_roots":{},"paths":{},"units":{},"references":{},"processes":{}}
for name in ("REA-Trial","Engenheira-reversa"):
 p=Path("/srv/projects")/name
 out["project_roots"][name]={"real":p.is_dir() and not p.is_symlink(),"archive_exists":(p/"archive").is_dir(),"owner":p.stat().st_uid if p.is_dir() else None,"archive_entries":len(list((p/"archive").iterdir())) if (p/"archive").is_dir() else None}
for s,n in sources.items():
 p=Path(s)
 try:
  st=p.lstat()
  x={"exists":True,"type":"symlink" if p.is_symlink() else "dir" if p.is_dir() else "file","owner":st.st_uid,"group":st.st_gid,"mode":oct(st.st_mode&0o777),"device":st.st_dev,"inode":st.st_ino}
  if p.is_symlink():x["target"]=os.readlink(s)
  if p.is_dir() and not p.is_symlink():
   arr=list(p.iterdir());x["children_count"]=len(arr);x["child_types"]={"dir":sum(q.is_dir() for q in arr),"file":sum(q.is_file() for q in arr),"link":sum(q.is_symlink() for q in arr)}
   x["names_safe"]=[q.name for q in arr if not any(w in q.name.lower() for w in ("secret","token","password","key","cred","session"))][:25]
  out["paths"][n]=x
 except FileNotFoundError:out["paths"][n]={"exists":False}
for n in ("rea-reversa-mcp","rea-mcp-oauth","rea-final","rea-mcp","nginx","ssh"):
 r=subprocess.run(["systemctl","show",n,"-p","ActiveState,UnitFileState,SubState"],capture_output=True,text=True,timeout=7)
 out["units"][n]=dict(l.split("=",1) for l in r.stdout.splitlines() if "=" in l)
 for f in (Path("/etc/systemd/system")/(n+".service"),Path("/lib/systemd/system")/(n+".service")):
  if f.is_file():
   b=f.read_bytes()
   out["units"][n]["source_file"]=str(f)
   out["units"][n]["external_ref_counts"]={s:b.count(s.encode()) for s in sources}
   out["units"][n]["project_ref_counts"]={s:b.count(s.encode()) for s in ("/srv/projects/REA-Trial","/srv/projects/Engenheira-reversa")}
   break
for s,n in sources.items():
 matches=[]
 for base in ("/etc/nginx","/etc/cron.d","/usr/local/sbin","/usr/local/bin"):
  p=Path(base)
  if not p.is_dir():continue
  for cur,dirs,files in os.walk(p,followlinks=False):
   if len(Path(cur).relative_to(p).parts)>2:dirs[:]=[];continue
   for name in files:
    f=Path(cur)/name
    try:
     if f.is_file() and not f.is_symlink() and f.stat().st_size<80000 and s.encode() in f.read_bytes():matches.append(str(f))
    except OSError:pass
 out["references"][n]=matches
print(json.dumps(out,sort_keys=True))
